    </div>
    <div class="feature-card">
      <div class="icon-box">⚡</div>
      <h3>Velocidade Imbatível</h3>
      <p>De PDF até resumo em menos de 30 segundos, mesmo em documentos de centenas de páginas.</p>
    </div>
  </div>
</section>

<!-- ============ DEMO INTERATIVA ============ -->
<section class="demo-section" id="demo">
  <div class="hero-content">
    <h2 class="demo-title">Veja na prática ⚡</h2>
    <p class="demo-sub">Digite ou selecione um arquivo e veja o PaperMind transformar em texto instantaneamente.</p>

    <div class="demo-tools">
      <div class="demo-input-wrap">
        <input type="text" class="demo-input" id="demoInput" placeholder="Cole aqui o texto do PDF ou..." autocomplete="off" />
        <button class="upload-btn">📄 Enviar</button>
      </div>
      <button class="simulate-btn" onclick="runDemo()">✨ Gerar Resumo</button>
