const wordCountEl = document.getElementById('wordCount');

function runDemo() {
  const input = document.getElementById('demoInput').value.trim();
  if (!input && !document.querySelectorAll('#demoInput:::-internal-placeholder').length) {
    // se nada foi digitado, simula mesmo assim (para demo)
