  }

  // Efeito de carregamento
  resultArea.classList.remove('show');
  const loading = document.createElement('div');
  loading.style.cssText = `
    margin-top:2rem; max-width:740px;margin-inline:auto;
    background:var(--bg-card);border-radius:20px;border:1px solid rgba(108,92,231,.18);
    padding:2rem;text-align:center;color:var(--accent-2);font-size:1rem;font-weight:600;
  `;
  loading.innerHTML = '<span>🔍 Analisando documento...</span>';
  resultArea.appendChild(loading);

  setTimeout(() => {
    loading.remove();
    resultArea.classList.add('show');

    // Contagem fictícia de palavras do exemplo
    const words = summaryText.innerText.split(/\s+/).length;
    wordCountEl.textContent = words;
  }, 1800);

  // Toast
